use std::fmt;
#[derive(Debug)]
enum AppError { Empty, TooLong(usize) }
impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            AppError::Empty => write!(f, "empty input"),
            AppError::TooLong(n) => write!(f, "too long: {n}"),
        }
    }
}
fn check(s: &str) -> Result<(), AppError> {
