use serde::{Serialize, Deserialize};
#[derive(Serialize, Deserialize, Debug)]
struct Task {
    id: u32,
    title: String,
    done: bool,
}

use std::fs;
fn load() -> Vec<Task> {
    fs::read_to_string("tasks.json")
        .ok()
        .and_then(|t| serde_json::from_str(&t).ok())
        .unwrap_or_default()
}
fn save(tasks: &[Task]) {
    let json = serde_json::to_string_pretty(tasks).unwrap();
    fs::write("tasks.json", json).unwrap();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut tasks = load();
    match args.get(1).map(|s| s.as_str()) {
        Some("add") => {
            let id = tasks.len() as u32 + 1;
            tasks.push(Task { id, title: args[2].clone(), done: false });
            save(&tasks);
        }
        Some("list") => {
            for t in &tasks {
                println!("[{}] {} {}", if t.done { "x" } else { " " }, t.id, t.title);
            }
        }
        _ => println!("usage: todo add <title> | list"),
    }
}

