fn mark_done(tasks: &mut Vec<Task>, id: u32) -> bool {
    for t in tasks.iter_mut() {
        if t.id == id {
            t.done = true;
            return true;
        }
    }
    false
}

fn pending(tasks: &[Task]) -> usize {
    tasks.iter().filter(|t| !t.done).count()
}
